import ast,copy,hashlib,json,pathlib,sqlite3,sys,types
from datetime import datetime,timezone
cfg=json.loads(sys.argv[1]);root=pathlib.Path(cfg["root"])
def pin(b):return {"bytes":len(b),"sha256":hashlib.sha256(b).hexdigest(),"git_blob":hashlib.sha1(b"blob "+str(len(b)).encode()+b"\0"+b).hexdigest()}
checks=0
def check(x,label):
    global checks
    checks+=1
    if not x:raise AssertionError(label)
old=(root/"tests/test_inspection.py").read_bytes()
needle=b"            ledger._db.set_authorizer(None)\n"
replacement=b"            # Python 3.10 requires a callable; None only disables it on 3.11+.\n            ledger._db.set_authorizer(lambda *_: sqlite3.SQLITE_OK)\n"
check(old.count(needle)==1,"one cleanup replacement")
new=old.replace(needle,replacement)
check(pin(old)["git_blob"]==cfg["expectations"]["old_blob"],"original exact helper")
check(pin(new)["git_blob"]==cfg["expectations"]["new_blob"] and pin(new)["sha256"]==cfg["expectations"]["new_sha256"],"exact frozen successor")
a,b=ast.parse(old),ast.parse(new)
def recv(t):return next(n for n in ast.walk(t) if isinstance(n,ast.FunctionDef) and n.name=="receive")
ra,rb=recv(a),recv(b)
ta=next(n for n in ra.body if isinstance(n,ast.Try));tb=next(n for n in rb.body if isinstance(n,ast.Try))
check(ast.dump(ast.Module(body=ta.body,type_ignores=[]))==ast.dump(ast.Module(body=tb.body,type_ignores=[])),"complete guarded try body unchanged")
check(ast.dump(ta.finalbody[1])==ast.dump(tb.finalbody[1]),"trace cleanup unchanged")
tb.finalbody[0]=copy.deepcopy(ta.finalbody[0])
check(ast.dump(a,include_attributes=False)==ast.dump(b,include_attributes=False),"only first finally statement AST changes")
source_before={str(p.relative_to(root)):pin(p.read_bytes()) for p in root.rglob("*") if p.is_file() and "__pycache__" not in p.parts}
sys.path.insert(0,str(root))
from fanout_engine import Ledger,Plan,Part,inspect_project
def module(name,data):
    m=types.ModuleType(name);m.__file__=str(root/"tests/test_inspection.py");exec(compile(data,m.__file__,"exec"),m.__dict__);return m
mods={"baseline":module("independent_original_test_helper",old),"candidate":module("independent_successor_test_helper",new)}
class Gate:
    def __init__(self,db,legacy):
        self.db=db;self.legacy=legacy;self.inside=False;self.installs=[];self.calls=[];self.traces=[]
    def __getattr__(self,name):return getattr(self.db,name)
    def set_authorizer(self,cb):
        name="None" if cb is None else getattr(cb,"__name__","callable")
        self.installs.append({"callback":name,"inside_inspector":self.inside})
        if cb is None and not self.legacy:return self.db.set_authorizer(None)
        def dispatch(action,first,second,database,trigger):
            # CPython3.10's C callback calls even None; a callback error returns DENY.
            result=sqlite3.SQLITE_DENY if cb is None else cb(action,first,second,database,trigger)
            self.calls.append({"callback":name,"action":action,"first":first,"second":second,"inside_inspector":self.inside,"result":result})
            return result
        return self.db.set_authorizer(dispatch)
    def set_trace_callback(self,cb):
        if cb is None:return self.db.set_trace_callback(None)
        def trace(sql):
            self.traces.append({"inside_inspector":self.inside,"sql":sql})
            cb(sql)
        return self.db.set_trace_callback(trace)
def setup(legacy):
    ledger=Ledger();gate=Gate(ledger._db,legacy);ledger._db=gate
    plan=Plan("independent-cleanup",(Part("one","Authored first."),Part("two","Authored second.",depends_on=("one",))))
    ledger.record_plan(plan);return ledger,gate,plan
def use(mod,ledger,project,kind="normal",code=None):
    gate=ledger._db;original=mod.inspect_project
    def observed(l,p):
        gate.inside=True
        try:
            if kind=="write":
                l._db.execute("UPDATE parts SET state='failed' WHERE part_id='one'")
                raise AssertionError("write unexpectedly permitted")
            result=inspect_project(l,p)
            if kind=="exception":raise LookupError("authored exception after actual snapshot")
            return result
        finally:gate.inside=False
    mod.inspect_project=observed
    try:return mod.InspectionTests().receive(ledger,project,code)
    finally:mod.inspect_project=original
out={}
for legacy in (True,False):
    label="modeled_cpython310_none_denial" if legacy else "native_cpython312_authorizer"
    ledger,gate,plan=setup(legacy)
    try:
        try:
            report=use(mods["baseline"],ledger,plan.project_id)
        except sqlite3.DatabaseError as error:
            check(legacy and "not authorized" in str(error),"baseline denial only in legacy model")
            check(any(c["callback"]=="None" and c["result"]==sqlite3.SQLITE_DENY and not c["inside_inspector"] for c in gate.calls),"baseline failure after inspector")
            baseline={"result":"post-inspection DatabaseError","message":str(error)}
        else:
            check(not legacy and report["queued_ready_ids"]==["one"],"native baseline control passes")
            baseline={"result":"native control passes"}
        check(len([x for x in gate.traces if x["inside_inspector"]])==1,"baseline actual guarded select completes")
    finally:ledger.close()
    ledger,gate,plan=setup(legacy)
    try:
        first=use(mods["candidate"],ledger,plan.project_id)
        check(first["queued_ready_ids"]==["one"],"initial candidate result")
        ledger.mark_dispatching(plan.project_id,"one","authored-worker",{"model":"authored"})
        ledger.mark_running(plan.project_id,"one","authored-task")
        second=use(mods["candidate"],ledger,plan.project_id)
        check(second["parts"][0]["state"]=="running","native transition between receives")
        missing=use(mods["candidate"],ledger,"absent","normal","project_not_found")
        check(missing.code=="project_not_found","typed refusal cleanup")
        before=list(gate.iterdump())
        try:use(mods["candidate"],ledger,plan.project_id,"exception")
        except LookupError as error:check(str(error)=="authored exception after actual snapshot","unexpected exception propagated")
        else:raise AssertionError("unexpected inspector exception swallowed")
        check(list(gate.iterdump())==before,"finally cleanup after unexpected exception")
        try:use(mods["candidate"],ledger,plan.project_id,"write")
        except sqlite3.DatabaseError as error:check("not authorized" in str(error),"active inspector UPDATE denied")
        else:raise AssertionError("active inspector write not denied")
        check(list(gate.iterdump())==before,"denied inspector mutation unchanged")
        third=Plan("after-exception",(Part("new","Authored new native plan."),))
        ledger.record_plan(third)
        final=use(mods["candidate"],ledger,third.project_id)
        check(final["queued_ready_ids"]==["new"],"native write and repeated receiving after exceptional cleanup")
        installs=gate.installs
        check(len(installs)==12,"six receives each install strict then cleanup")
        check(all(installs[i]["callback"]=="authorize" and installs[i+1]["callback"]=="<lambda>" for i in range(0,len(installs),2)),"no None cleanup and strict reinstallation each time")
        check(not any(x["inside_inspector"] for x in installs),"no authorizer replacement while inspector executing")
        inside=[x for x in gate.calls if x["inside_inspector"]]
        check(inside and all(x["callback"]=="authorize" for x in inside),"all inspector authorization uses strict callback")
        denied=[x for x in inside if x["result"]==sqlite3.SQLITE_DENY]
        check(len(denied)==1 and denied[0]["action"]==sqlite3.SQLITE_UPDATE,"exact injected update denied")
        traces=[x for x in gate.traces if x["inside_inspector"]]
        check(len(traces)==5 and all(x["sql"].lstrip().upper().startswith("SELECT") for x in traces),"five successful or typed-refusal snapshots are single SELECTs")
        check(any(x["callback"]=="<lambda>" and not x["inside_inspector"] and x["action"]==sqlite3.SQLITE_INSERT for x in gate.calls),"post-inspection native writes allowed")
        out[label]={"baseline":baseline,"candidate":"pass","receives":6,"actual_guarded_selects":len(traces),"denied_inside":denied,"callback_installations":installs,"native_after_exception_project":third.project_id,"exception_propagates":True,"rows_unchanged_by_exception_and_injection":True}
    finally:ledger.close()
source_after={str(p.relative_to(root)):pin(p.read_bytes()) for p in root.rglob("*") if p.is_file() and "__pycache__" not in p.parts}
check(source_before==source_after,"all original candidate15source files unchanged")
